class SshForwardingFactory(object):

    @staticmethod
    def create(ssh_connection, forward_address):
        """
        create ssh forwarding.
        :param ssh_connection: SshConnection, ssh connection.
        :param forward_address: Address, forwarding address.
        :return SshForwarding: ssh forwarding object
        """
        ssh_forwarding = SshForwarding(
            ssh_connection=ssh_connection,
            forward_address=forward_address)

        return ssh_forwarding


class SshHopFactory(object):

    @staticmethod
    def create(host, user, password, port, pkey, key_filename, timeout, initialization_commands):
        """
        create a ssh hop.
        :param host: str, hop ip address.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, hop ssh port.
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return SshHop: ssh hop.
        """
        ssh_connection = SshConnection(
            host=host,
            port=port,
            user=user,
            password=password,
            pkey=pkey,
            key_filename=key_filename,
            timeout=timeout)

        hop = SshHop(ssh_connection=ssh_connection, initialization_commands=initialization_commands)
        return hop


class SshForwardableHopFactory(object):

    @staticmethod
    def create(host, user, password, port, pkey, key_filename, timeout, initialization_commands):
        """
        create a ssh forwardable hop.
        this hop support direct forwarding.
        :param host: str, hop ip address.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, hop ssh port.
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return SshForwardableHop: ssh forwardable hop.
        """
        ssh_connection = SshConnection(
            host=host,
            port=port,
            user=user,
            password=password,
            pkey=pkey,
            key_filename=key_filename,
            timeout=timeout)

        hop = SshForwardableHop(ssh_connection=ssh_connection, initialization_commands=initialization_commands)

        return hop


class SshForwardableReverseHopFactory(object):

    @staticmethod
    def create(host, user, password, port, pkey, key_filename, timeout, initialization_commands):
        """
        create a ssh forwardable hop.
        this hop support direct forwarding.
        :param host: str, ip address of hop.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return SshForwardableReverseHop: ssh forwardable reverse hop.
        """
        ssh_connection = SshConnection(
            host=host,
            port=port,
            user=user,
            password=password,
            pkey=pkey,
            key_filename=key_filename,
            timeout=timeout)

        ssh_reverse_forwarding = SshReverseForwarding(ssh_connection)

        hop = SshForwardableReverseHop(
            ssh_connection=ssh_connection,
            ssh_reverse_forwarding=ssh_reverse_forwarding,
            initialization_commands=initialization_commands)

        return hop


class ExtraSshdForwardableHopFactory(object):

    @staticmethod
    def create(new_sshd_port, host, user, password, port, sudo_prefix, pkey, key_filename, timeout, initialization_commands):
        """
        create a hop, need startup new sshd service for getting ssh forwarding function.
        :param new_sshd_port: str, new sshd service binding port.
        :param host: str, ip address of hop.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param sudo_prefix: str, if login username is not root, should specify sudo_prefix="sudo ".
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return ExtraSshdForwardableHop: extra sshd forwardable hop.
        """
        ssh_connection = SshConnection(
            host=host,
            port=port,
            user=user,
            password=password,
            pkey=pkey,
            key_filename=key_filename,
            timeout=timeout)

        sshd = Sshd(ssh_connection=ssh_connection,
                    port=new_sshd_port,
                    sudo_prefix=sudo_prefix)

        new_ssh_connection = SshConnection(host=host,
                                           port=new_sshd_port,
                                           user=user,
                                           password=password)

        hop = ExtraSshdForwardableHop(
            ssh_connection=ssh_connection,
            sshd=sshd,
            new_ssh_connection=new_ssh_connection,
            initialization_commands=initialization_commands)

        return hop


class LxcSshdForwardableHopFactory(object):

    @staticmethod
    def create(host_hop, containerid, host, user, password, port, sudo_prefix, timeout, initialization_commands):
        """
        create LxcSshdForwardableHop object, under steps will be processed.
        step1: using "lxc-attach"command enter into container
        step2: startup a sshd service with input confguration.
        step3: create ssh connection to container.
        :param host_hop: Hop, The host hop which container belong to.
        :param containerid: str, container id.
        :param host: str, ip address of hop.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param sudo_prefix: str, if login username is not root, should specify sudo_prefix="sudo ".
        :param timeout: float, timeout (in seconds) for ssh connecting, default 10s.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return LxcSshdForwardableHop: lxc extra sshd forwardable hop.
        """

        sshd = LxcSshd(ssh_connection=host_hop.ssh_connection,
                       containerid=containerid,
                       host=host,
                       port=port,
                       sudo_prefix=sudo_prefix)

        ssh_connection = SshConnection(host=host,
                                       port=port,
                                       user=user,
                                       password=password,
                                       timeout=timeout)

        hop = LxcSshdForwardableHop(
            sshd=sshd,
            ssh_connection=ssh_connection,
            initialization_commands=initialization_commands)

        return hop


class ExtraSshdSshReverseHopFactory(object):

    @staticmethod
    def create(host, user, password, port, new_sshd_port, sudo_prefix, pkey, key_filename, timeout, initialization_commands):
        """
        create a hop, need startup new sshd service and support reverse forwarding.
        :param new_sshd_port: str, new sshd service binding port.
        :param host: str, ip address of hop.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param sudo_prefix: str, if login username is not root, should specify sudo_prefix="sudo ".
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return ExtraSshdSshReverseHop: extra sshd reverse hop.
        """
        ssh_connection = SshConnection(
            host=host,
            port=port,
            user=user,
            password=password,
            pkey=pkey,
            key_filename=key_filename,
            timeout=timeout)

        sshd = Sshd(ssh_connection=ssh_connection,
                    port=new_sshd_port,
                    sudo_prefix=sudo_prefix)

        new_ssh_connection = SshConnection(host=host,
                                           port=new_sshd_port,
                                           user=user,
                                           password=password,
                                           pkey=pkey,
                                           key_filename=key_filename)

        ssh_reverse_forwarding = SshReverseForwarding(new_ssh_connection)

        hop = ExtraSshdSshReverseHop(ssh_connection=ssh_connection,
                                     sshd=sshd,
                                     new_ssh_connection=new_ssh_connection,
                                     ssh_reverse_forwarding=ssh_reverse_forwarding,
                                     initialization_commands=initialization_commands)

        return hop


class SshForwardableNetcatReverseHopFactory(object):

    @staticmethod
    def create(host,
               local_netcat_port,
               remote_netcat_host,
               remote_netcat_port,
               user,
               password,
               port,
               nc_listen_template,
               nc_connect_template,
               pkey,
               key_filename,
               timeout,
               initialization_commands):
        """
        create a forwardable netact hop, support starting and stopping netcat forwarding.
        :param host: str, ip address of hop.
        :param local_netcat_port: int, netcat local listening port.
        :param remote_netcat_host: str, the remote host ip address which netcat forward local service to
        :param remote_netcat_port: str, the remote port which netcat forward local service to
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param nc_listen_template: str, netcat listen command template.
        :param nc_connect_template: str, netcat connect command template.
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return SshForwardableNetcatReverseHop: ssh forwardable netcat reverse Hop.
        """
        ssh_connection = SshConnection(host=host,
                                       port=port,
                                       user=user,
                                       password=password,
                                       pkey=pkey,
                                       key_filename=key_filename,
                                       timeout=timeout)

        netcat_reverse_server = NetcatReverseForwarding(local_port=local_netcat_port,
                                                        remote_host=remote_netcat_host,
                                                        remote_port=remote_netcat_port,
                                                        nc_listen_template=nc_listen_template,
                                                        nc_connect_template=nc_connect_template)

        hop = SshForwardableNetcatReverseHop(ssh_connection=ssh_connection,
                                             netcat_reverse_server=netcat_reverse_server,
                                             initialization_commands=initialization_commands)
        netcat_reverse_server.attach_executor(hop)

        return hop


class RemoteServiceFactory(object):

    @staticmethod
    def create(ip, port):
        """
        create a remote service, the service will be mapped to user with port forwarding.
        the service will be used in creating ssh forwarding or reverse branch.
        :param ip: str, remote service ip address.
        :param port: str, remote service port.
        :return RemoteService: remote service object
        """
        return RemoteService(ip, port)


class NetcatRemoteServiceFactory(object):

    @staticmethod
    def create(service_port,
               remote_netcat_host,
               remote_netcat_port,
               nc_listen_template,
               nc_connect_template):
        """
        create a netcat remote service, the service will be mapped to user with port forwarding.
        the service will be used in creating netcat reverse forwarding branch
        :param service_port: str, remote service port
        :param remote_netcat_host: str, the remote host ip address which netcat forward local service to
        :param remote_netcat_port: str, the remote port which netcat forward local service to
        :param nc_listen_template: str, netcat listen command template.
        :param nc_connect_template: str, netcat connect command template.
        :return StartableNetcatRemoteService: startable netcat remoteService object.
        """

        netcat_reverse_server = NetcatReverseForwarding(local_port=service_port,
                                                        remote_host=remote_netcat_host,
                                                        remote_port=remote_netcat_port,
                                                        nc_listen_template=nc_listen_template,
                                                        nc_connect_template=nc_connect_template)

        remote_service = StartableNetcatRemoteService(netcat_reverse_server=netcat_reverse_server)

        return remote_service


class KubectlForwardRemoteServiceFactory(object):

    @staticmethod
    def create(namespace,
               pod,
               port):
        """
        create a kubectl port forward remote service.
        :param namespace: str, kubernetes namespace.
        :param pod: str, kubernetes pod name.
        :param port: int, service port in pod container.
        :return StartableKubectlForwardRemoteService: kubectl port forward remote service.
        """
        kubectl_portforward = KubectlPortForward(namespace=namespace,
                                                 pod=pod,
                                                 port=port)

        remote_service = StartableKubectlForwardRemoteService(kubectl_portforward=kubectl_portforward)

        return remote_service


class BranchFactory(object):

    def __init__(self):
        self._ssh_forwarding_factory = SshForwardingFactory()

    def create(self, hops):
        raise NotImplementedError

    def _config_hops_ssh_forwarding(self, hops):
        pre_hop = hops[0]
        for hop in hops[1:]:
            self._create_ssh_forwarding(from_hop=pre_hop, to_hop=hop)
            pre_hop = hop

    def _create_ssh_forwarding(self, from_hop, to_hop):
        for to_ssh_connection in to_hop.ssh_connections:
            ssh_forwarding = self._ssh_forwarding_factory.create(
                from_hop.forwardable_ssh_connection, to_ssh_connection.address)
            to_ssh_connection.ssh_forwarding = ssh_forwarding
            to_ssh_connection.add_prerequisite(ssh_forwarding)


class SshForwardingBranchFactory(BranchFactory):

    LOCAL_HOST = "127.0.0.1"

    def create(self, hops, forwarding_port, remote_service):
        """
        create a forward ssh branch.
        build dependency relationships between hops.
        config hops based dependency information.
        :param hops: list, hop object list.
        :param forwarding_port: int, forwarding port mapping to remote service,
            which is specified as test vm server port.
        :param remote_service: RemoteService, remote service.
        :return Branch: ssh forwarding branch.
        """

        self._config_hops_ssh_forwarding(hops)

        forward_service_hop = hops[-1]
        if isinstance(remote_service, StartableRemoteService):
            forward_service_hop = hops[-2]
            remote_service.attach_executor(hops[-1])

        ssh_forwarding = self._ssh_forwarding_factory.create(
            forward_service_hop.forwardable_ssh_connection, remote_service.address)

        ssh_forwarding.add_prerequisite(remote_service)

        forwarding_server = ForwardingServer(
            ssh_forwarding=ssh_forwarding, server_address=(self.LOCAL_HOST, forwarding_port))

        return Branch(nodes=hops + [forwarding_server])


class SshReverseForwardingBranchFactory(BranchFactory):

    def create(self, hops, forwarding_port, remote_service):
        """
        create a reverse ssh branch.
        build dependency relationships between hops.
        config hops based dependency information.
        :param hops: list, hop object list.
        :param forwarding_port: int, forwarding port mapping to remote service,
            which is specified as last hop ssh listen server port.
        :param remote_service: RemoteService, remote service.
        :return Branch: ssh reverse forwarding branch.
        """

        self._config_hops_ssh_forwarding(hops)

        data_exchange = DataExchange(remote_service)

        forward_service_hop = hops[-1]
        forward_service_hop.reverse_forwarding(forwarding_port, data_exchange)

        return Branch(nodes=hops)


class NetcatReverseForwardingBranchFactory(BranchFactory):

    def create(self, hops, startable_remote_service):
        """
        create a reverse netcat branch.
        build dependency relationships between hops.
        config hops based dependency information.
        :param hops: list, hop object list.
        :param startable_remote_service: StartableNetcatRemoteService, startable remote service.
        :return Branch: netcat reverse branch.
        """

        self._config_hops_ssh_forwarding(hops)
        startable_remote_service.attach_executor(hops[-1])

        return Branch(nodes=hops + [startable_remote_service])
